{
  "name": "ACQ2106 模块化高速数据采集机箱",
  "name_en": "ACQ2106 modular high-speed data acquisition chassis",
  "manufacturer": "D-TACQ",
  "description": "ACQ2106 是一类模块化高速数据采集机箱，用于承载多通道采集模块并进行统一的时钟、触发和同步管理。它常用于实验室中的瞬态信号记录、波形采集以及需要多设备同步的测量场景。",
  "description_en": "The ACQ2106 is a modular high-speed data acquisition chassis that hosts multi-channel acquisition modules and provides centralized clock, trigger, and synchronization control. It is commonly used in laboratories for transient recording, waveform capture, and synchronized measurements across multiple devices.",
  "actions": [
    {
      "action_name": "auto-set_mb_clk",
      "description": "设置主板时钟的频率、时钟源和输入参考频率。",
      "description_en": "Set the motherboard clock frequency, clock source, and input reference frequency."
    },
    {
      "action_name": "auto-set_sync_routing_slave",
      "description": "将同步信号路由配置为从机模式。",
      "description_en": "Configure synchronization signal routing for slave operation."
    },
    {
      "action_name": "auto-set_master_trg",
      "description": "设置主触发源、触发边沿和使能状态。",
      "description_en": "Set the master trigger source, trigger edge, and enable state."
    },
    {
      "action_name": "auto-set_MR",
      "description": "设置 MR 功能的使能状态以及相关事件选择和分频参数。",
      "description_en": "Configure the MR function enable state and its related event-selection and division parameters."
    },
    {
      "action_name": "auto-wr_PPS_active",
      "description": "设置 PPS 有效状态。",
      "description_en": "Set the PPS active state."
    }
  ],
  "tag_hints": [
    "modular data acquisition",
    "high-speed waveform digitization",
    "trigger and clock distribution",
    "multi-device synchronization",
    "transient recorder",
    "multi-channel measurement"
  ]
}

